inline ::flatbuffers::Offset<TRP> CreateTRP(::flatbuffers::FlatBufferBuilder &_fbb, const TRPT *_o, const ::flatbuffers::rehasher_function_t *_rehasher) {
  return TRP::Pack(_fbb, _o, _rehasher);
}

