inline const TRP *GetTRP(const void *buf) {
  return ::flatbuffers::GetRoot<TRP>(buf);
}

inline const TRP *GetSizePrefixedTRP(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<TRP>(buf);
}

inline const char *TRPIdentifier() {
  return "$TRP";
}

inline bool TRPBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, TRPIdentifier());
}

inline bool SizePrefixedTRPBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, TRPIdentifier(), true);
}

template <bool B = false>
inline bool VerifyTRPBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<TRP>(TRPIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedTRPBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<TRP>(TRPIdentifier());
}

inline void FinishTRPBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<TRP> root) {
  fbb.Finish(root, TRPIdentifier());
}

inline void FinishSizePrefixedTRPBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<TRP> root) {
  fbb.FinishSizePrefixed(root, TRPIdentifier());
}

inline std::unique_ptr<TRPT> UnPackTRP(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<TRPT>(GetTRP(buf)->UnPack(res));
}

inline std::unique_ptr<TRPT> UnPackSizePrefixedTRP(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<TRPT>(GetSizePrefixedTRP(buf)->UnPack(res));
}

